instruction: Debug the following C++ code that is supposed to print the elements of a 2D array but instead crashes without any clear error message. Also, enhance the code by adding functions to perform column and row major traversals of the 2D array.

response: Because the buggy code isn’t shown, the most common reasons a “print 2D array” program crashes are:
- **Out-of-bounds indexing** (loop uses `<=` instead of `<`, swapped row/col limits, wrong hard-coded sizes).
- **Using `int**` without allocating each row** (dereferencing uninitialized pointers).
- **Mismatched dimensions** between allocation and traversal.

A safe way to avoid these issues is to store the matrix contiguously and index with `r*cols + c`. Below is a corrected, crash-free example that also adds **row-major** and **column-major** traversal functions:

```cpp
#include <iostream>
#include <vector>

using std::size_t;

// Access helper for a contiguous 2D matrix
int& at(std::vector<int>& a, size_t rows, size_t cols, size_t r, size_t c) {
    return a[r * cols + c];
}
const int& at(const std::vector<int>& a, size_t rows, size_t cols, size_t r, size_t c) {
    return a[r * cols + c];
}

void printRowMajor(const std::vector<int>& a, size_t rows, size_t cols) {
    for (size_t r = 0; r < rows; ++r) {
        for (size_t c = 0; c < cols; ++c) {
            std::cout << at(a, rows, cols, r, c) << ' ';
        }
        std::cout << '\n';
    }
}

void traverseRowMajor(const std::vector<int>& a, size_t rows, size_t cols) {
    std::cout << "Row-major traversal: ";
    for (size_t r = 0; r < rows; ++r)
        for (size_t c = 0; c < cols; ++c)
            std::cout << at(a, rows, cols, r, c) << ' ';
    std::cout << '\n';
}

void traverseColumnMajor(const std::vector<int>& a, size_t rows, size_t cols) {
    std::cout << "Column-major traversal: ";
    for (size_t c = 0; c < cols; ++c)
        for (size_t r = 0; r < rows; ++r)
            std::cout << at(a, rows, cols, r, c) << ' ';
    std::cout << '\n';
}

int main() {
    const size_t rows = 3, cols = 4;
    std::vector<int> a(rows * cols);

    // Fill example data
    int v = 1;
    for (size_t r = 0; r < rows; ++r)
        for (size_t c = 0; c < cols; ++c)
            at(a, rows, cols, r, c) = v++;

    std::cout << "Matrix (row-major print):\n";
    printRowMajor(a, rows, cols);

    traverseRowMajor(a, rows, cols);
    traverseColumnMajor(a, rows, cols);
}
```

