public class Main {
    public static String transform(String s) {
        String up = s.toUpperCase();
        StringBuilder out = new StringBuilder(up.length());
        for (int i = 0; i < up.length(); i++) {
            char c = up.charAt(i);
            switch (c) {
                case 'A': out.append('1'); break;
                case 'E': out.append('2'); break;
                case 'I': out.append('3'); break;
                case 'O': out.append('4'); break;
                case 'U': out.append('5'); break;
                default:  out.append(c);
            }
        }
        return out.toString();
    }

    public static void main(String[] args) {
        String input = "Hello World";
        System.out.println(transform(input)); // H2LL4 W4RLD
    }
}
```

